54	      min-height: 100dvh;
55	      display: grid;
56	      place-items: center;
57	      padding: 1rem;
58	      background: var(--bg);
59	      color: var(--text);
60	      font-family: system-ui, -apple-system, sans-serif;
61	    }
62	    main {
63	      width: 100%;
64	      display: flex;
65	      flex-direction: column;
66	      align-items: center;
67	      text-align: center;
68	    }
69	    button {
70	      display: block;
71	      width: min(360px, 100%);
72	      aspect-ratio: 1;
73	      border: 0;
74	      border-radius: 50%;
75	      background: none;
76	      color: var(--fg);
77	      cursor: pointer;
78	      touch-action: manipulation;
79	      -webkit-tap-highlight-color: transparent;
80	      transition: color 0.4s ease;
81	    }
82	    button:focus-visible {
83	      outline: 3px solid var(--fg);
84	      outline-offset: 8px;
85	    }
86	    svg {
87	      display: block;
88	      width: 100%;
89	      height: 100%;
90	      overflow: visible;
91	      opacity: 0.9;
92	      filter: drop-shadow(0 8px 16px var(--shadow));
93	      transition: opacity 0.3s ease, color 0.4s ease;
94	    }
95	    svg circle {
96	      transition: r 0.3s ease;
97	    }
98	    button:active svg,
99	    button:focus-visible svg {
100	      opacity: 1;
101	    }
102	    button.color-changed svg {
103	      animation: pulse 0.5s ease-out;
104	    }
