125	        transform: scale(1.05);
126	      }
127	      button:active svg {
128	        transform: scale(0.97);
129	      }
130	    }
131	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
132	      button:hover:not(:active) svg {
133	        transform: scale(1.05);
134	      }
135	    }
136	    .status {
137	      margin-top: 2rem;
138	      font-weight: 600;
139	    }
