154	</head>
155	<body>
156	  <main>
157	    <button type="button" aria-label="Change circle color" aria-describedby="status hint">
158	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
159	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
160	      </svg>
161	    </button>
162	    <p class="status" id="status" role="status">Blue</p>
163	    <p class="hint" id="hint">Click to change color (or press <kbd>Space</kbd>)</p>
164	  </main>
165	  <script>
166	    const button = document.querySelector('button');
167	    const status = document.querySelector('.status');
168	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
169	    const storageKey = 'circle-color';
170	
171	    const savedColor = localStorage.getItem(storageKey);
172	    let index = Math.max(colors.indexOf(savedColor), 0);
173	
174	    function applyColor() {
175	      const color = colors[index];
176	      if (color === 'blue') {
177	        delete button.dataset.color;
178	      } else {
179	        button.dataset.color = color;
180	      }
181	      status.textContent = color[0].toUpperCase() + color.slice(1);
182	      localStorage.setItem(storageKey, color);
183	
184	      button.classList.add('color-changed');
185	      button.addEventListener('animationend', () => {
186	        button.classList.remove('color-changed');
187	      }, { once: true });
188	    }
189	
190	    applyColor();
191	
192	    function changeColor() {
193	      index = (index + 1) % colors.length;
194	      applyColor();
195	    }
196	
197	    button.addEventListener('click', changeColor);
198	
199	    document.addEventListener('keydown', (e) => {
200	      if ((e.code === 'Space' || e.code === 'Enter') && document.activeElement === button) {
201	        e.preventDefault();
202	        changeColor();
203	      }
204	    });
205	  </script>
206	</body>
207	</html>
